import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import sharp from 'sharp';
import { describe, expect, it } from 'vitest';

/**
 * iOS only uses a launch image whose media query matches the device exactly;
 * when none does it stretches whatever it has, which is how a landscape iPad
 * ends up showing the portrait artwork stretched across the screen.
 *
 * The links are generated by `bun run generate-assets` and pasted into
 * index.html. This guards the paste: every declared device size must point at
 * an image whose pixel size is exactly what that device has, and every size
 * must be declared with both orderings of `device-width`/`device-height` in
 * landscape, because iPadOS is inconsistent about which one it reports.
 */

interface SplashLink {
  declaredWidth: number;
  declaredHeight: number;
  ratio: number;
  landscape: boolean;
  href: string;
}

const ROOT = resolve(__dirname, '../..');
const LINK = /<link rel="apple-touch-startup-image" media="([^"]+)" href="([^"]+)" \/>/g;

/** The mark's box is this fraction of the launch image's shorter edge. */
const SPLASH_MARK_RATIO = 0.62;
/** The same fraction index.html uses: `#boot-splash svg { width: 62vmin }`. */
const BOOT_SPLASH_RATIO = Number(/#boot-splash svg \{[\s\S]*?width: ([\d.]+)vmin/.exec(readFileSync(resolve(ROOT, 'index.html'), 'utf8'))?.[1]) / 100;
/** The artwork's ink fills this much of its own square box. */
const INK_RATIO = 0.775;
const RATIO_TOLERANCE = 0.04;

function splashLinks(): SplashLink[] {
  const html = readFileSync(resolve(ROOT, 'index.html'), 'utf8');
  return [...html.matchAll(LINK)].map((match) => {
    const media = match[1];
    return {
      declaredWidth: Number(/\(device-width: (\d+)px\)/.exec(media)?.[1]),
      declaredHeight: Number(/\(device-height: (\d+)px\)/.exec(media)?.[1]),
      ratio: Number(/\(-webkit-device-pixel-ratio: (\d+)\)/.exec(media)?.[1]),
      landscape: /\(orientation: landscape\)/.test(media),
      href: match[2],
    };
  });
}

/** Width and height straight out of the PNG's IHDR chunk. */
function pngSize(path: string): { width: number; height: number } {
  const buffer = readFileSync(resolve(ROOT, 'public', path.replace(/^\//, '')));
  expect(buffer.subarray(1, 4).toString('ascii')).toBe('PNG');
  return { width: buffer.readUInt32BE(16), height: buffer.readUInt32BE(20) };
}

describe('iOS launch images', () => {
  const links = splashLinks();

  it('points every size at an image of exactly that pixel size', () => {
    for (const link of links) {
      const size = pngSize(link.href);
      // A landscape link always points at the wide artwork, whether the device
      // reports its width or its height in `device-width`.
      const short = Math.min(link.declaredWidth, link.declaredHeight) * link.ratio;
      const long = Math.max(link.declaredWidth, link.declaredHeight) * link.ratio;
      const expected = link.landscape ? { width: long, height: short } : { width: short, height: long };
      expect(size, `${link.href} for ${link.declaredWidth}x${link.declaredHeight}`).toEqual(expected);
    }
  });

  it('declares a tablet size in landscape whichever way round iPadOS reports it', () => {
    const landscapeTablets = links.filter((link) => link.landscape && Math.min(link.declaredWidth, link.declaredHeight) >= 744);
    const declared = new Set(landscapeTablets.map((link) => `${link.declaredWidth}x${link.declaredHeight}`));
    for (const link of landscapeTablets) {
      const swapped = `${link.declaredHeight}x${link.declaredWidth}`;
      expect(declared.has(swapped), `${swapped} (swap of ${link.declaredWidth}x${link.declaredHeight})`).toBe(true);
    }
  });

  it('covers both orientations for every device size', () => {
    const sizes = new Map<string, Set<boolean>>();
    for (const link of links) {
      const key = `${Math.min(link.declaredWidth, link.declaredHeight)}x${Math.max(link.declaredWidth, link.declaredHeight)}@${link.ratio}`;
      const orientations = sizes.get(key) ?? new Set<boolean>();
      orientations.add(link.landscape);
      sizes.set(key, orientations);
    }
    for (const [key, orientations] of sizes) {
      expect([...(orientations ?? [])].sort(), key).toEqual([false, true]);
    }
  });

  it('covers the iPads that are readily available today', () => {
    const declared = links.map((link) => `${Math.min(link.declaredWidth, link.declaredHeight)}x${Math.max(link.declaredWidth, link.declaredHeight)}`);
    // iPad 11"/10.9" (820x1180), iPad 11th gen and Air 11" (834x1210),
    // iPad Pro 13"/Air 13" (M4) (1032x1376), iPad mini (744x1133).
    for (const size of ['820x1180', '834x1210', '1032x1376', '744x1133']) {
      expect(declared, size).toContain(size);
    }
  });

  it('draws the mark, so the launch has no iconless first frame', async () => {
    // An installed app shows this image before any of the app can run. With only
    // a background in it the launch starts blank and the mark shows up later -
    // the flash this guards against.
    for (const link of links.slice(0, 6)) {
      const file = resolve(ROOT, 'public', link.href.replace(/^\//, ''));
      const { data, info } = await sharp(file).raw().toBuffer({ resolveWithObject: true });
      const first = data.subarray(0, info.channels);
      let drawn = false;
      for (let i = info.channels; i < data.length && !drawn; i += info.channels) {
        for (let channel = 0; channel < info.channels; channel += 1) {
          if (data[i + channel] !== first[channel]) {
            drawn = true;
            break;
          }
        }
      }
      expect(drawn, `${link.href} is a flat background`).toBe(true);
    }
  });

  it('draws the mark where the splash draws it, so the hand-off does not jump', async () => {
    // index.html's #boot-splash continues the launch image. If the two draw the
    // mark at different sizes or places, the swap reads as a flash.
    expect(BOOT_SPLASH_RATIO, '#boot-splash svg width in index.html').toBeCloseTo(SPLASH_MARK_RATIO, 2);
    const expectedInk = INK_RATIO * SPLASH_MARK_RATIO;

    for (const link of links.slice(0, 4)) {
      const file = resolve(ROOT, 'public', link.href.replace(/^\//, ''));
      const { data, info } = await sharp(file).raw().toBuffer({ resolveWithObject: true });
      const background = [...data.subarray(0, info.channels)];
      const differs = (offset: number) => data.subarray(offset, offset + info.channels).some((value, channel) => Math.abs(value - background[channel]) > 12);

      let left = info.width;
      let right = -1;
      let top = info.height;
      let bottom = -1;
      for (let y = 0; y < info.height; y += 1) {
        for (let x = 0; x < info.width; x += 1) {
          if (!differs((y * info.width + x) * info.channels)) {
            continue;
          }
          if (x < left) {left = x;}
          if (x > right) {right = x;}
          if (y < top) {top = y;}
          if (y > bottom) {bottom = y;}
        }
      }

      const ink = Math.max(right - left + 1, bottom - top + 1) / Math.min(info.width, info.height);
      expect(ink, `${link.href} mark size`).toBeGreaterThan(expectedInk - RATIO_TOLERANCE);
      expect(ink, `${link.href} mark size`).toBeLessThan(expectedInk + RATIO_TOLERANCE);
      // Centred, like the splash: an offset mark would jump on the hand-off.
      expect(Math.abs((left + right) / 2 - info.width / 2), `${link.href} mark horizontal centre`).toBeLessThan(info.width * 0.02);
      expect(Math.abs((top + bottom) / 2 - info.height / 2), `${link.href} mark vertical centre`).toBeLessThan(info.height * 0.02);
    }
  });
});
